                comps.append(cells)
    big = max(comps, key=len)
    rs = [r for r, c in big]; cs = [c for r, c in big]
    r0, r1 = min(rs), max(rs); c0, c1 = min(cs), max(cs)
    P = [row[c0:c1 + 1] for row in grid[r0:r1 + 1]]
    bh = len(P); bw = len(P[0])
    mr = bh // 2; mc = bw // 2
    out = [row[:] for row in grid]
    for comp in comps:
        if comp is big:
            continue
